source("helpers/network-recipes.R", local = TRUE)

# Generated by the unchanged C++ wrappers at ce1cb0f0. Includes parameter
# edits, treatments, nonzero initial states, queue settings and all three
# transmission modes; full histories and transmission events must match.
reference <- read.csv("helpers/network-recipes-reference.csv", stringsAsFactors = FALSE)
expect_identical(reference[names(recipe_cases)], recipe_cases)
actual <- recipe_reference()
for (i in seq_along(actual))
  expect_identical(recipe_fingerprint(actual[[i]]), reference$fingerprint[i],
    info = paste(unlist(recipe_cases[i, ]), collapse = "/"))

# Reconfigure initial states after cloning (not just before copying).
for (kind in names(recipe_initial)) {
  m <- recipe_model(kind)
  copied <- clone_epi(m)
  initial_states(copied, recipe_initial[[kind]])
  initial_states(m, recipe_initial[[kind]])
  run(copied, ndays = 20L, seed = 42L)
  run(m, ndays = 20L, seed = 42L)
  expect_identical(recipe_snapshot(copied), recipe_snapshot(m))
}

# Native callbacks and initializer factories must also survive thread copies.
for (kind in c("SIR", "SIS", "SEIR", "SIRD", "SISD", "SEIRD")) {
  m <- recipe_model(kind, custom = TRUE)
  copied <- clone_epi(m)
  run_multiple(m, ndays = 20L, nsims = 4L, seed = 123L,
    saver = make_saver("total_hist"), nthreads = 1L, verbose = FALSE)
  run_multiple(copied, ndays = 20L, nsims = 4L, seed = 123L,
    saver = make_saver("total_hist"), nthreads = 2L, verbose = FALSE)
  expect_equal(run_multiple_get_results(m), run_multiple_get_results(copied))
}

expect_error(update_fun_incubation(-1L))
expect_error(update_fun_incubation(c(1L, 2L)))
expect_error(update_fun_recovery(c("a", "b")))
expect_error(update_fun_recovery(NA_character_))

# Misconfigured custom models must report errors rather than dereference an
# absent virus in these newly exposed native updates.
for (fun in list(update_fun_incubation(0L), update_fun_recovery("rate"))) {
  m <- Model()
  add_param(m, "rate", 1)
  add_state(m, "invalid", fun)
  agents_smallworld(m, n = 10L, k = 2L, d = FALSE, p = 0)
  queuing_off(m)
  verbose_off(m)
  expect_error(run(m, ndays = 2L, seed = 1L), "requires a virus")
}
